import { executeWithPow, type PowChallenge, type PowRunner } from "../../../core/src/pow_gate.ts";
import { apiErrorCode, type ApiLike } from "./api.ts";
import { QrLoginError, type QrLoginOptions } from "./qr_login_types.ts";
import type { AuthSession } from "./types.ts";
import type { RegisterFields, RegisterOptions } from "./session.ts";

type Deps = {
  api: ApiLike;
  powRunner?: PowRunner;
  accountLinkToken?: string | null;
};

type QrDeps = Deps & { ensureCurrent: () => void };
type QrStart = { qr_token: string; expires_in: number };
type QrPoll =
  | { status: "pending" }
  | { status: "denied" }
  | { status: "cancelled" }
  | ({ status: "approved" } & AuthSession);

export async function registerAuth(
  deps: Deps,
  fields: RegisterFields,
  opts: RegisterOptions,
): Promise<AuthSession> {
  const body: Record<string, unknown> = {
    username: fields.username,
    password: fields.password,
    name: fields.name,
    legal_accepted: fields.legal_accepted,
  };
  // Older embedded shells may still send this retired acknowledgement. Preserve their wire shape
  // during the compatibility window, but new clients omit it entirely.
  if (fields.age_confirmed !== undefined) body.age_confirmed = fields.age_confirmed;
  if (fields.phone) body.phone = fields.phone;
  if (fields.email) body.email = fields.email;
  if (fields.locale) body.locale = fields.locale;
  if (fields.invite_code) body.invite_code = fields.invite_code;
  if (deps.accountLinkToken) body.account_link_token = deps.accountLinkToken;
  return executeWithPow(
    (pow) => deps.api.post<AuthSession>("/v1/auth/register", pow ? { ...body, ...pow } : body),
    {
      fetchChallenge: () => deps.api.get<PowChallenge>("/v1/auth/pow"),
      ...(deps.powRunner ? { runner: deps.powRunner } : {}),
      ...(opts.signal ? { signal: opts.signal } : {}),
      ...(opts.onPowProgress ? { onProgress: opts.onPowProgress } : {}),
    },
  );
}

function cancelled(): QrLoginError {
  return new QrLoginError("QR_CANCELLED", "QR login cancelled");
}

function pause(ms: number, signal?: AbortSignal): Promise<void> {
  if (signal?.aborted) return Promise.reject(cancelled());
  if (ms <= 0) return Promise.resolve();
  return new Promise<void>((resolve, reject) => {
    const abort = (): void => {
      clearTimeout(timer);
      signal?.removeEventListener("abort", abort);
      reject(cancelled());
    };
    const timer = setTimeout(() => {
      signal?.removeEventListener("abort", abort);
      resolve();
    }, ms);
    signal?.addEventListener("abort", abort, { once: true });
  });
}

function transient(error: unknown): boolean {
  if (!error || typeof error !== "object") return false;
  const name = "name" in error ? String((error as { name?: unknown }).name ?? "") : "";
  return name === "NetworkError" || name === "TypeError";
}

export async function loginQr(deps: QrDeps, opts: QrLoginOptions): Promise<AuthSession> {
  const now = opts.now ?? Date.now;
  const interval = Math.max(0, Math.floor(opts.pollIntervalMs ?? 1_000));
  let token: string | null = null;
  let terminal = false;
  opts.onStatus?.("starting");
  try {
    const start = await executeWithPow(
      (pow) => deps.api.post<QrStart>("/v1/auth/qr/start", pow ?? {}),
      {
        fetchChallenge: () => deps.api.get<PowChallenge>("/v1/auth/pow"),
        ...(deps.powRunner ? { runner: deps.powRunner } : {}),
        ...(opts.signal ? { signal: opts.signal } : {}),
        ...(opts.onPowProgress ? { onProgress: opts.onPowProgress } : {}),
      },
    );
    deps.ensureCurrent();
    if (typeof start?.qr_token !== "string" || !/^[0-9a-f]{96}$/i.test(start.qr_token)
      || !Number.isFinite(start.expires_in) || start.expires_in <= 0) {
      throw new QrLoginError("QR_INVALID_RESPONSE", "Invalid QR login start response");
    }
    token = start.qr_token;
    const expiresAt = now() + Math.floor(start.expires_in * 1_000);
    opts.onReady?.({ token, link: `greenchat://auth/qr/${encodeURIComponent(token)}`, expiresAt });
    opts.onStatus?.("waiting");

    for (;;) {
      if (opts.signal?.aborted) throw cancelled();
      deps.ensureCurrent();
      if (now() >= expiresAt) throw new QrLoginError("QR_EXPIRED", "QR login expired");
      let poll: QrPoll;
      try {
        poll = await deps.api.post<QrPoll>("/v1/auth/qr/poll", {
          qr_token: token,
          ...(opts.devicePubkey ? { device_pubkey: opts.devicePubkey } : {}),
          ...(deps.accountLinkToken ? { account_link_token: deps.accountLinkToken } : {}),
        });
      } catch (error) {
        if (opts.signal?.aborted) throw cancelled();
        if (apiErrorCode(error) === "NOT_FOUND") throw new QrLoginError("QR_EXPIRED", "QR login expired");
        if (!transient(error)) throw error;
        opts.onStatus?.("offline");
        await pause(interval, opts.signal);
        opts.onStatus?.("waiting");
        continue;
      }
      deps.ensureCurrent();
      if (!poll || typeof poll !== "object" || typeof poll.status !== "string") {
        throw new QrLoginError("QR_INVALID_RESPONSE", "Invalid QR login poll response");
      }
      if (poll.status === "pending") {
        opts.onStatus?.("waiting");
        await pause(interval, opts.signal);
        continue;
      }
      if (poll.status === "denied") {
        terminal = true;
        throw new QrLoginError("QR_DENIED", "QR login denied");
      }
      if (poll.status === "cancelled") {
        terminal = true;
        throw cancelled();
      }
      if (poll.status !== "approved") throw new QrLoginError("QR_INVALID_RESPONSE", "Unknown QR login status");
      terminal = true;
      return poll;
    }
  } finally {
    if (token && !terminal) {
      try { await deps.api.post("/v1/auth/qr/cancel", { qr_token: token }); }
      catch { /* The short server TTL is the offline fallback. */ }
    }
  }
}
